-- Run once in a NEW Supabase project. Do not use on an existing unrelated database.
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, username text unique not null, owner boolean not null default false, enabled boolean not null default true, permissions text[] not null default '{}');
create table public.site(id integer primary key check(id=1), draft jsonb not null, published jsonb not null, revision integer not null default 0);
create table public.activity(id bigint generated always as identity primary key, actor text not null, action text not null, created_at timestamptz default now());
create table public.applications(id uuid primary key default gen_random_uuid(), form_id text not null, form_title text not null, answers jsonb not null, status text not null default 'New', notes text not null default '', created_at timestamptz default now());
create table public.versions(id bigint generated always as identity primary key, snapshot jsonb not null, created_at timestamptz default now());
insert into public.site(id,draft,published) values(1,$json${"title":"Calcite","headline":"Your next Minecraft adventure.","description":"Minecraft gameplay, Bedwars, Shorts and more. Welcome to the official home of Calcite.","channel":"https://www.youtube.com/@Calcitemc","community":"","announcement":"","maintenance":false,"features":{"calendar":true,"roadmap":false,"applications":false,"community":true},"videos":[],"calendar":[],"roadmap":[],"categories":["Minecraft"],"forms":[],"contact":"","accent":"#d4dce9"}$json$,$json${"title":"Calcite","headline":"Your next Minecraft adventure.","description":"Minecraft gameplay, Bedwars, Shorts and more. Welcome to the official home of Calcite.","channel":"https://www.youtube.com/@Calcitemc","community":"","announcement":"","maintenance":false,"features":{"calendar":true,"roadmap":false,"applications":false,"community":true},"videos":[],"calendar":[],"roadmap":[],"categories":["Minecraft"],"forms":[],"contact":"","accent":"#d4dce9"}$json$);
alter table public.profiles enable row level security;
alter table public.site enable row level security;
alter table public.activity enable row level security;
alter table public.applications enable row level security;
alter table public.versions enable row level security;
revoke all on public.profiles,public.site,public.activity,public.applications,public.versions from anon,authenticated;
create function public.allowed(p text) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and enabled and (owner or (p<>'Users' and p=any(permissions)))); $$;
create function public.is_staff() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and enabled); $$;
create policy profiles_read on public.profiles for select to authenticated using (id=auth.uid() and enabled or public.allowed('Users'));
create policy site_read on public.site for select to authenticated using (public.is_staff());
create policy app_read on public.applications for select to authenticated using(public.allowed('Review'));
create policy activity_read on public.activity for select to authenticated using(public.allowed('Activity'));
create policy versions_read on public.versions for select to authenticated using(public.allowed('Publish'));
grant select on public.profiles,public.site,public.activity,public.applications,public.versions to authenticated;
-- Public visitors only receive the published snapshot, never drafts or private projects.
create function public.get_public_site() returns jsonb language sql stable security definer set search_path='' as $$ select published || jsonb_build_object('roadmap',coalesce((select jsonb_agg(x) from jsonb_array_elements(published->'roadmap') x where x->'public'='true'::jsonb),'[]'::jsonb)) from public.site where id=1; $$;
create function public.log_action(action_text text) returns void language sql security definer set search_path='' as $$ insert into public.activity(actor,action) select username,action_text from public.profiles where id=auth.uid(); $$;
create function public.save_section(section_name text,patch jsonb,expected_revision integer) returns integer language plpgsql security definer set search_path='' as $$
declare keys text[]; r integer; begin
if not public.allowed(section_name) then raise exception 'Permission denied'; end if;
keys:=case section_name when 'Website' then array['title','headline','description','channel','community','contact','accent','maintenance'] when 'Content' then array['videos','categories'] when 'Calendar' then array['calendar'] when 'Announcements' then array['announcement'] when 'Roadmap' then array['roadmap'] when 'Applications' then array['forms'] when 'Features' then array['features'] else null end;
if keys is null or jsonb_typeof(patch)<>'object' or exists(select 1 from jsonb_object_keys(patch) k where not(k=any(keys))) or octet_length(patch::text)>250000 then raise exception 'Invalid section data'; end if;
update public.site set draft=draft||patch,revision=revision+1 where id=1 and revision=expected_revision returning revision into r;
if r is null then raise exception 'Another change was saved. Reload your draft.'; end if; perform public.log_action('Saved '||section_name); return r; end; $$;
create function public.publish_site(expected_revision integer) returns integer language plpgsql security definer set search_path='' as $$ declare r integer; previous jsonb; begin if not public.allowed('Publish') then raise exception 'Permission denied'; end if; select published into previous from public.site where id=1 and revision=expected_revision for update; if not found then raise exception 'Reload your draft first'; end if; insert into public.versions(snapshot) values(previous); update public.site set published=draft,revision=revision+1 where id=1 returning revision into r; perform public.log_action('Published website'); return r; end; $$;
create function public.set_access(target uuid,new_enabled boolean,new_permissions text[]) returns void language plpgsql security definer set search_path='' as $$ begin if not public.allowed('Users') then raise exception 'Permission denied'; end if; if not new_permissions <@ array['Website','Content','Calendar','Announcements','Roadmap','Applications','Features','Publish','Review','Activity'] then raise exception 'Invalid permissions'; end if; update public.profiles set enabled=new_enabled,permissions=new_permissions where id=target and not owner; if not found then raise exception 'Cannot modify this account'; end if; perform public.log_action('Updated team access'); end; $$;
create function public.submit_application(form_id text,answers jsonb) returns void language plpgsql security definer set search_path='' as $$ declare s jsonb; f jsonb; q jsonb; a jsonb; idx integer:=0; begin select published into s from public.site where id=1; if s->'features'->'applications' <> 'true'::jsonb or s->'maintenance'='true'::jsonb then raise exception 'Closed'; end if; select x into f from jsonb_array_elements(s->'forms') x where x->>'id'=form_id and x->'open'='true'::jsonb and (coalesce(x->>'closes','')='' or x->>'closes'>=current_date::text) limit 1; if f is null or jsonb_typeof(answers)<>'array' or octet_length(answers::text)>20000 or jsonb_array_length(answers)<>jsonb_array_length(f->'questions') then raise exception 'Invalid application'; end if; for q in select * from jsonb_array_elements(f->'questions') loop a:=answers->idx; if a->>'label' is distinct from q->>'label' or jsonb_typeof(a->'answer') is distinct from 'string' or length(a->>'answer')>1000 or (q->'required'='true'::jsonb and trim(a->>'answer')='') then raise exception 'Invalid answer'; end if; idx:=idx+1; end loop; if (select count(*) from public.applications where created_at>now()-interval '1 hour')>=30 then raise exception 'Please try later'; end if; insert into public.applications(form_id,form_title,answers) values(form_id,f->>'title',answers); end; $$;
create function public.review_application(application_id uuid,new_status text,new_notes text) returns void language plpgsql security definer set search_path='' as $$ begin if not public.allowed('Review') then raise exception 'Permission denied'; end if; if new_status not in ('New','Shortlisted','Accepted','Rejected','Archived') or length(new_notes)>5000 then raise exception 'Invalid review'; end if; update public.applications set status=new_status,notes=new_notes where id=application_id; perform public.log_action('Reviewed application'); end; $$;
create function public.delete_application(application_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not public.allowed('Review') then raise exception 'Permission denied'; end if; delete from public.applications where id=application_id; perform public.log_action('Deleted application'); end; $$;
revoke execute on function public.log_action(text) from public,anon,authenticated;
revoke execute on function public.allowed(text),public.is_staff(),public.get_public_site(),public.save_section(text,jsonb,integer),public.publish_site(integer),public.set_access(uuid,boolean,text[]),public.submit_application(text,jsonb),public.review_application(uuid,text,text),public.delete_application(uuid) from public,anon,authenticated;
grant execute on function public.get_public_site(),public.submit_application(text,jsonb) to anon,authenticated;
grant execute on function public.allowed(text),public.is_staff(),public.save_section(text,jsonb,integer),public.publish_site(integer),public.set_access(uuid,boolean,text[]),public.review_application(uuid,text,text),public.delete_application(uuid) to authenticated;
